import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { phonePlans } from '../config/phonePlanConfig';
import PhoneSalesFilterForm from './PhoneSalesFilterForm';
import PhoneSalesInputForm from './PhoneSalesInputForm';
import PhoneSalesResult from './PhoneSalesResult';

export default function PhoneSalesCalculator() {
  const navigate = useNavigate();

  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    devicePrice: 0,
    partialPayment: 0,
    discountType: '',
    installments: 24,
  });

  const [results, setResults] = useState({
    monthlyPlanCost: 0,
    deviceInstallment: 0,
    totalPayment: 0,
    savings: 0,
  });

  const [showResult, setShowResult] = useState(false);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');

  const monthlyRate = 0.059 / 12;

  const handleFilterChange = (name, value) => {
    setValues(prev => {
      const next = { ...prev, [name]: value };
      if (name === 'dataFilter') {
        next.category = '';
        next.planId = '';
        next.planCost = 0;
      }
      if (name === 'category') {
        next.planId = '';
        next.planCost = 0;
      }
      if (name === 'planId') {
        const plan = phonePlans.find(p => p.id === value);
        next.planCost = plan ? plan.monthlyFee : 0;
      }
      return next;
    });
    setShowResult(false);
    setRecommendedDiscount('');
  };

  const handleChange = e => {
    const { name, value } = e.target;
    setValues(prev => ({
      ...prev,
      [name]: ['installments','partialPayment'].includes(name)
        ? Number(value)
        : value,
    }));
    setShowResult(false);
    setRecommendedDiscount('');
  };

  const selectedPlan = phonePlans.find(p => p.id === values.planId);
  const others = selectedPlan?.others;

  const calculate = () => {
    const { devicePrice, partialPayment, planCost, discountType, installments } = values;
    if (!planCost) return;
    const principal = devicePrice - partialPayment;

    // 약정할인 시나리오
    const cost1_plan = Math.round(planCost * 0.75);
    const pv1 = principal;
    const cost1_device = installments > 0
      ? Math.ceil((pv1 * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;
    const total1 = cost1_plan + cost1_device;

    // 단말할인 시나리오
    const cost2_plan = Math.round(planCost);
    const pv2 = principal * 0.75;
    const cost2_device = installments > 0
      ? Math.ceil((pv2 * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;
    const total2 = cost2_plan + cost2_device;

    // 사용자 선택 결과
    const monthlyPlanCost = discountType === 'contract' ? cost1_plan : cost2_plan;
    const deviceInstallment = discountType === 'device' ? cost2_device : cost1_device;
    const totalPayment = monthlyPlanCost + deviceInstallment;

    // 절감/손해액 계산
    let savings = 0;
    if (discountType === 'contract') savings = total2 - total1;
    else if (discountType === 'device') savings = total1 - total2;

    // 추천 할인
    const best = total1 < total2 ? '약정할인' : '단말할인';

    setResults({ monthlyPlanCost, deviceInstallment, totalPayment, savings });
    setRecommendedDiscount(best);
    setShowResult(true);
  };

  return (
    <div className="flex flex-col items-center min-h-screen bg-gray-50 p-4">
      <div className="w-full max-w-lg bg-white shadow rounded-2xl p-6 mb-4">
        <h2 className="text-2xl font-bold mb-6 text-center">KT 핸드폰 계산기</h2>

        <PhoneSalesFilterForm values={values} onFilterChange={handleFilterChange} />
        <PhoneSalesInputForm
          values={values}
          onChange={handleChange}
          others={others}
          recommendedDiscount={recommendedDiscount}
        />

        <button
          type="button"
          onClick={calculate}
          className="w-full bg-blue-500 text-white py-2 rounded-md hover:bg-blue-600 transition mb-4"
        >
          계산하기
        </button>

        {showResult && <PhoneSalesResult {...results} />}
      </div>

      <button
        type="button"
        onClick={() => navigate('/')}
        className="block mx-auto bg-gray-200 text-gray-700 rounded py-2 px-4 hover:bg-gray-300 transition"
      >
        메인 메뉴로 돌아가기
      </button>
    </div>
  );
}