import React from 'react';

export default function PhoneSalesResult({ monthlyPlanCost, deviceInstallment, totalPayment, savings }) {
  // 양수면 절감(+) / 음수면 손해(-)
  const sign = savings > 0 ? '+' : savings < 0 ? '-' : '';
  const abs = Math.abs(savings);

  return (
    <div className="bg-gray-100 p-4 rounded-lg space-y-2">
      <p className="text-lg">
        월 요금제: <span className="font-semibold">{monthlyPlanCost.toLocaleString()}원</span>
      </p>
      <p className="text-lg">
        단말 할부 대금: <span className="font-semibold">{deviceInstallment.toLocaleString()}원</span>
      </p>
      <p className="text-lg">
        월 총 납부 예상 금액: <span className="font-semibold">{totalPayment.toLocaleString()}원</span>
      </p>
      {savings !== 0 && (
        <p className={`text-lg ${savings > 0 ? 'text-green-600' : 'text-red-600'}`}>
          {sign}{abs.toLocaleString()}원
        </p>
      )}
    </div>
  );
}