import React from 'react';

export default function PhoneSalesInputForm({ values, onChange, others, recommendedDiscount }) {
  return (
    <>
      {/* 단말기 출고가 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">단말기 출고가</label>
        <input
          type="number"
          name="devicePrice"
          value={values.devicePrice}
          onChange={onChange}
          onFocus={e => e.target.select()}
          className="w-full border p-2 rounded-md"
          placeholder="원"
        />
      </div>

      {/* 부분 수납 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">부분 수납</label>
        <input
          type="number"
          name="partialPayment"
          value={values.partialPayment}
          onChange={onChange}
          onFocus={e => e.target.select()}
          className="w-full border p-2 rounded-md"
          placeholder="선납금액 입력"
        />
      </div>

      {/* 추가 혜택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">추가 혜택</label>
        <div className="w-full border p-2 rounded-md bg-gray-50 text-sm whitespace-pre-wrap">
          {others || '선택된 요금제의 혜택 정보가 없습니다.'}
        </div>
      </div>

      {/* 할인 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">할인 선택</label>
        <select
          name="discountType"
          value={values.discountType}
          onChange={onChange}
          className="w-full border p-2 rounded-md"
        >
          <option value="">할인 없음</option>
          <option value="contract">약정할인 (25%)</option>
          <option value="device">단말할인 (25%)</option>
        </select>
        {recommendedDiscount && (
          <p className="mt-1 text-sm text-blue-600">추천 할인: {recommendedDiscount}</p>
        )}
      </div>

      {/* 할부개월 */}
      <div className="mb-6">
        <label className="block text-sm font-medium mb-1">할부개월</label>
        <select
          name="installments"
          value={values.installments}
          onChange={onChange}
          className="w-full border p-2 rounded-md"
        >
          {[6, 12, 24, 36].map(n => <option key={n} value={n}>{n}개월</option>)}
        </select>
      </div>
    </>
  );
}