import React from 'react';
import { phonePlans } from '../config/phonePlanConfig';

export default function PhoneSalesFilterForm({ values, onFilterChange }) {
  const plans = phonePlans;

  const dataOptions = Array.from(
    new Set(
      plans
        .filter(p => !values.category || p.category === values.category)
        .filter(p => !values.planId   || p.id === values.planId)
        .map(p => p.data)
    )
  );

  const categoryOptions = Array.from(
    new Set(
      plans
        .filter(p => !values.dataFilter || p.data === values.dataFilter)
        .filter(p => !values.planId      || p.id === values.planId)
        .map(p => p.category)
    )
  );

  const planOptions = plans.filter(
    p => (!values.dataFilter || p.data === values.dataFilter) &&
         (!values.category   || p.category === values.category)
  );

  return (
    <div className="mb-6">
      {/* 데이터 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">데이터</label>
        <select
          name="dataFilter"
          value={values.dataFilter}
          onChange={e => onFilterChange('dataFilter', e.target.value)}
          className="w-full border p-2 rounded-md"
        >
          <option value="">전체</option>
          {dataOptions.map(d => <option key={d} value={d}>{d}</option>)}
        </select>
      </div>

      {/* 카테고리 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">카테고리</label>
        <select
          name="category"
          value={values.category}
          onChange={e => onFilterChange('category', e.target.value)}
          className="w-full border p-2 rounded-md"
        >
          <option value="">전체</option>
          {categoryOptions.map(cat => <option key={cat} value={cat}>{cat}</option>)}
        </select>
      </div>

      {/* 요금제 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">요금제</label>
        <select
          name="planId"
          value={values.planId}
          onChange={e => onFilterChange('planId', e.target.value)}
          className="w-full border p-2 rounded-md"
        >
          <option value="">전체</option>
          {planOptions.map(p => (
            <option key={p.id} value={p.id}>
              {p.name} ({p.monthlyFee.toLocaleString()}원)
            </option>
          ))}
        </select>
      </div>
    </div>
  );
}